  $('#inspectorBorder').value=rgbToHex(cs.borderColor,'#e2d6e5');$('#inspectorBorderWidth').value=parseInt(cs.borderWidth)||0;$('#inspectorRadius').value=parseInt(cs.borderRadius)||0;$('#inspectorPadding').value=parseInt(cs.paddingTop)||0;$('#inspectorOpacity').value=Math.round((parseFloat(cs.opacity)||1)*100);$('#inspectorVAlign').value=cs.justifyContent||'flex-start';$('#inspectorAutoHeight').checked=el.dataset.autoHeight!=='0';
  $('#inspectorBold').classList.toggle('active',parseInt(cs.fontWeight)>=700);$('#inspectorItalic').classList.toggle('active',cs.fontStyle==='italic');$('#inspectorUnderline').classList.toggle('active',cs.textDecorationLine.includes('underline'));
