function parsePageRange(value,max){const out=new Set();String(value||'').split(',').map(x=>x.trim()).filter(Boolean).forEach(part=>{const m=part.match(/^(\d+)\s*-\s*(\d+)$/);if(m){let a=+m[1],b=+m[2];if(a>b)[a,b]=[b,a];for(let n=a;n<=b;n++)if(n>=1&&n<=max)out.add(n)}else{const n=+part;if(n>=1&&n<=max)out.add(n)}});return [...out].sort((a,b)=>a-b)}
