async function loadPdfFile(file){toast('PDF wird geladen …');const lib=await pdfLib(),buf=await file.arrayBuffer(),pdf=await lib.getDocument({data:buf}).promise,id='pdf'+Date.now()+Math.random().toString(36).slice(2,5);materialDocs.set(id,pdf);const card=document.createElement('div');card.className='materialDoc';card.dataset.materialId=id;card.innerHTML='<div class="materialDocTitle"><b>📄 '+esc(file.name)+'</b><div class="materialDocMeta"><span>'+pdf.numPages+' Seiten</span><button class="materialDelete" type="button" title="Aus Material entfernen" aria-label="Aus Material entfernen">🗑</button></div></div><div class="materialDocTools"><label>Seiten <input class="pageRangeInput" inputmode="numeric" placeholder="z. B. 3-7, 10"></label><button class="rangeSelect" type="button">Bereich wählen</button><button class="selectAllPages" type="button">Alle</button><button class="clearPageSelection" type="button">Keine</button></div><div class="materialSelectionRow"><span class="selectionCount">Keine Auswahl</span><button class="addSelectedPages" type="button" disabled>Auswahl aufs Board</button></div><div class="pageStrip"></div>';$('#materialList .materialEmpty')?.remove();$('#materialList').appendChild(card);card.querySelector('.materialDelete').onclick=()=>removeMaterialDoc(id,card);card.querySelector('.rangeSelect').onclick=()=>{const nums=parsePageRange(card.querySelector('.pageRangeInput').value,pdf.numPages),set=new Set(nums);card.querySelectorAll('.pageThumb').forEach(b=>setPageSelected(b,set.has(+b.dataset.page)));syncDocSelection(card)};card.querySelector('.selectAllPages').onclick=()=>{card.querySelectorAll('.pageThumb').forEach(b=>setPageSelected(b,true));syncDocSelection(card)};card.querySelector('.clearPageSelection').onclick=()=>{card.querySelectorAll('.pageThumb').forEach(b=>setPageSelected(b,false));syncDocSelection(card)};card.querySelector('.addSelectedPages').onclick=()=>placePdfPages(id,selectedPages(card),file.name);updateMaterialListState();const strip=card.querySelector('.pageStrip');for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),vp=page.getViewport({scale:.32}),cv=document.createElement('canvas');cv.width=Math.ceil(vp.width);cv.height=Math.ceil(vp.height);await page.render({canvasContext:cv.getContext('2d'),viewport:vp}).promise;const b=document.createElement('button');b.type='button';b.className='pageThumb';b.dataset.page=n;b.draggable=true;b.setAttribute('aria-pressed','false');b.innerHTML='<span>Seite '+n+'</span>';b.prepend(cv);b.onclick=e=>{if(e.shiftKey){const last=+card.dataset.lastPage||n,a=Math.min(last,n),z=Math.max(last,n);card.querySelectorAll('.pageThumb').forEach(x=>{const p=+x.dataset.page;if(p>=a&&p<=z)setPageSelected(x,true)})}else setPageSelected(b,!b.classList.contains('selected'));card.dataset.lastPage=n;syncDocSelection(card)};b.ondblclick=()=>placePdfPage(id,n,file.name);b.ondragstart=e=>{e.dataTransfer.effectAllowed='copy';e.dataTransfer.setData('application/x-kathleen-pdf-page',JSON.stringify({id,page:n,name:file.name}))};strip.appendChild(b)}toast(pdf.numPages+' PDF-Seiten bereit')}
async function renderPdfPage(id,n){const pdf=materialDocs.get(id);if(!pdf)return null;const page=await pdf.getPage(n),base=page.getViewport({scale:1}),renderScale=Math.min(2,1400/base.width),vp=page.getViewport({scale:renderScale}),cv=document.createElement('canvas');cv.width=Math.ceil(vp.width);cv.height=Math.ceil(vp.height);await page.render({canvasContext:cv.getContext('2d'),viewport:vp}).promise;return{src:cv.toDataURL('image/jpeg',.92),ratio:base.width/base.height}}
async function placePdfPage(id,n,name,x=null,y=null,silent=false){const rendered=await renderPdfPage(id,n);if(!rendered)return null;const w=700,h=w/rendered.ratio,c=boardCenter();snapshot();const el=renderItem({id:'i'+Date.now()+Math.random().toString(36).slice(2,5),type:'widget',x:x??c.x-w/2,y:y??c.y-h/2,w,h,locked:false,aspect:w/h,material:'material',html:'<div class="pageBadge">'+esc(name)+' · '+n+'</div><img class="materialImage" src="'+rendered.src+'" alt="PDF Seite '+n+'">'});select(el);persist();if(!silent)toast('Seite '+n+' aufs Board gelegt');return el}
async function placePdfPages(id,pages,name){if(!pages?.length)return;toast(pages.length+' Seiten werden eingefügt …');const c=boardCenter(),cols=Math.min(3,Math.max(1,Math.ceil(Math.sqrt(pages.length)))),gap=55,placed=[];for(let i=0;i<pages.length;i++){const rendered=await renderPdfPage(id,pages[i]);if(!rendered)continue;const w=520,h=w/rendered.ratio,row=Math.floor(i/cols),col=i%cols,x=c.x+(col-(cols-1)/2)*(w+gap)-w/2,y=c.y+row*(h+gap)-h/2;snapshot();const el=renderItem({id:'i'+Date.now()+Math.random().toString(36).slice(2,5),type:'widget',x,y,w,h,locked:false,aspect:w/h,material:'material',html:'<div class="pageBadge">'+esc(name)+' · '+pages[i]+'</div><img class="materialImage" src="'+rendered.src+'" alt="PDF Seite '+pages[i]+'">'});placed.push(el)}if(placed.length)applySelection(placed);persist();toast(placed.length+' Seiten aufs Board gelegt')}
async function handleMaterialFiles(files,clientX=null,clientY=null,mode='library'){for(const f of files){try{if(f.type==='application/pdf'||/\.pdf$/i.test(f.name))await loadPdfFile(f);else if(f.type.startsWith('image/')){if(mode==='direct'){const src=await fileDataURL(f);let x=null,y=null;if(clientX!=null){const p=pos({clientX,clientY});x=p.x-250;y=p.y-180}await addMaterialImage(src,f.name,x,y)}else await loadImageMaterial(f)}}catch(e){console.error(e);toast(e.message||'Material konnte nicht geladen werden')}}}
