async function renderBoardLibrary(){const list=$('#boardLibraryList'),rows=(await dbAll()).sort((x,y)=>String(y.updatedAt).localeCompare(String(x.updatedAt)));list.innerHTML=rows.map(r=>'<article class="boardCard '+(r.id===currentBoardId?'current':'')+'" data-board-id="'+esc(r.id)+'"><div class="boardPreview">'+(r.preview?'<img src="'+r.preview+'" alt="">':'<div class="boardPreviewEmpty">Board</div>')+'</div><div class="boardCardBody"><div class="boardCardTop"><div><b>'+esc(r.name||'Mein Board')+'</b><small>Zuletzt '+esc(fmtBoardDate(r.updatedAt))+'</small></div>'+(r.id===currentBoardId?'<span class="currentBadge">Geöffnet</span>':'')+'</div><div class="boardCardActions"><button data-board-open="'+esc(r.id)+'">Öffnen</button><button data-board-duplicate="'+esc(r.id)+'">Duplizieren</button><button data-board-rename="'+esc(r.id)+'">Umbenennen</button><button class="danger" data-board-delete="'+esc(r.id)+'">Löschen</button></div></div></article>').join('')||'<div class="materialEmpty">Noch keine Boards.</div>';$$('[data-board-open]').forEach(b=>b.onclick=()=>openBoardById(b.dataset.boardOpen));$$('[data-board-duplicate]').forEach(b=>b.onclick=()=>duplicateBoardById(b.dataset.boardDuplicate));$$('[data-board-rename]').forEach(b=>b.onclick=()=>renameBoardById(b.dataset.boardRename));$$('[data-board-delete]').forEach(b=>b.onclick=()=>deleteBoardById(b.dataset.boardDelete))}
async function showBoardLibrary(){await persistNow();await renderBoardLibrary();$('#boardLibraryModal').classList.remove('hidden')}
function hideBoardLibrary(){$('#boardLibraryModal').classList.add('hidden')}
async function openBoardById(id){if(id===currentBoardId){hideBoardLibrary();return}await persistNow();const rec=await dbGet(id);if(!rec)return;currentBoardId=id;localStorage.setItem(CURRENT_BOARD_KEY,id);history=[];future=[];applyBoardData(rec.data);hideBoardLibrary();toast('Board geöffnet')}
async function createNewBoard(){await persistNow();const name=(prompt('Name des neuen Boards','Neues Board')||'').trim();if(!name)return;const now=new Date().toISOString(),data={id:'board-'+Date.now()+Math.random().toString(36).slice(2,6),name,createdAt:now,updatedAt:now,bg:'',items:[],strokes:[]};await dbPut({id:data.id,name,createdAt:now,updatedAt:now,preview:boardPreview(data),data});currentBoardId=data.id;localStorage.setItem(CURRENT_BOARD_KEY,currentBoardId);history=[];future=[];applyBoardData(data);hideBoardLibrary();toast('Neues Board erstellt')}
async function duplicateBoardById(id){const rec=await dbGet(id);if(!rec)return;const now=new Date().toISOString(),data=structuredClone(rec.data);data.id='board-'+Date.now()+Math.random().toString(36).slice(2,6);data.name=(rec.name||'Board')+' – Kopie';data.createdAt=now;data.updatedAt=now;await dbPut({id:data.id,name:data.name,createdAt:now,updatedAt:now,preview:rec.preview||boardPreview(data),data});await renderBoardLibrary();toast('Board dupliziert')}
async function renameBoardById(id){const rec=await dbGet(id);if(!rec)return;const name=(prompt('Board umbenennen',rec.name||'Mein Board')||'').trim();if(!name)return;rec.name=name;rec.updatedAt=new Date().toISOString();rec.data.name=name;rec.data.updatedAt=rec.updatedAt;await dbPut(rec);if(id===currentBoardId){board.name=name;board.updatedAt=rec.updatedAt;setBoardTitle()}await renderBoardLibrary();toast('Board umbenannt')}
async function deleteBoardById(id){const rec=await dbGet(id);if(!rec||!confirm('Board „'+(rec.name||'Mein Board')+'“ wirklich löschen?'))return;await dbRemove(id);let rows=await dbAll();if(id===currentBoardId){if(!rows.length){const now=new Date().toISOString(),data={id:'board-'+Date.now(),name:'Mein Board',createdAt:now,updatedAt:now,bg:'',items:[],strokes:[]};await dbPut({id:data.id,name:data.name,createdAt:now,updatedAt:now,preview:boardPreview(data),data});rows=[await dbGet(data.id)]}const next=rows.sort((x,y)=>String(y.updatedAt).localeCompare(String(x.updatedAt)))[0];currentBoardId=next.id;localStorage.setItem(CURRENT_BOARD_KEY,currentBoardId);history=[];future=[];applyBoardData(next.data)}await renderBoardLibrary();toast('Board gelöscht')}
async function importBoardFile(file){try{const data=JSON.parse(await file.text());if(!data||!Array.isArray(data.items)||!Array.isArray(data.strokes))throw Error('Ungültiges Board');const now=new Date().toISOString();data.id='board-'+Date.now()+Math.random().toString(36).slice(2,6);data.name=data.name||file.name.replace(/\.json$/i,'')||'Importiertes Board';data.createdAt=now;data.updatedAt=now;await dbPut({id:data.id,name:data.name,createdAt:now,updatedAt:now,preview:boardPreview(data),data});await renderBoardLibrary();toast('Board importiert')}catch(e){console.error(e);toast('Import fehlgeschlagen')}}
