async function rpc(n,b){const r=await fetch(SB+n,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json'},body:JSON.stringify(b||{})});const raw=await r.text(),x=raw?(()=>{try{return JSON.parse(raw)}catch(e){return raw}})():null;if(!r.ok){const msg=(x&&typeof x==='object'&&(x.message||x.hint||x.details))||raw||('Supabase '+r.status);const err=new Error(msg);err.status=r.status;err.code=x?.code||'';throw err}return x}
