function loadTeacherWindowLayout(){try{return JSON.parse(localStorage.getItem(TEACHER_WINDOW_KEY)||'null')||{mode:'float',minimized:false,x:null,y:null}}catch(e){return{mode:'float',minimized:false,x:null,y:null}}}
function saveTeacherWindowLayout(v){localStorage.setItem(TEACHER_WINDOW_KEY,JSON.stringify(v))}
function clampTeacherWindow(panel,x,y){const r=panel.getBoundingClientRect(),pad=8,maxX=Math.max(pad,innerWidth-r.width-pad),maxY=Math.max(68,innerHeight-r.height-pad);return{x:Math.min(Math.max(pad,x),maxX),y:Math.min(Math.max(68,y),maxY)}}
function applyTeacherWindowLayout(){const p=$('#studentsPanel');if(!p)return;const st=loadTeacherWindowLayout();p.classList.remove('dockLeft','dockRight','floating','minimized');p.style.left='';p.style.right='';p.style.top='';p.style.bottom='';p.style.transform='';if(st.minimized)p.classList.add('minimized');if(st.mode==='left')p.classList.add('dockLeft');else if(st.mode==='right')p.classList.add('dockRight');else{p.classList.add('floating');requestAnimationFrame(()=>{const pr=p.getBoundingClientRect();const x=Number.isFinite(st.x)?st.x:Math.max(80,innerWidth-pr.width-24),y=Number.isFinite(st.y)?st.y:86;const pos=clampTeacherWindow(p,x,y);p.style.left=pos.x+'px';p.style.top=pos.y+'px'})}updateTeacherWindowButtons()}
function updateTeacherWindowButtons(){const p=$('#studentsPanel');if(!p)return;const st=loadTeacherWindowLayout();$('#teacherDockLeft')?.classList.toggle('active',st.mode==='left');$('#teacherFloat')?.classList.toggle('active',st.mode==='float');$('#teacherDockRight')?.classList.toggle('active',st.mode==='right');if($('#teacherMinimize'))$('#teacherMinimize').textContent=st.minimized?'□':'—'}
function setTeacherWindowMode(mode){const st=loadTeacherWindowLayout();st.mode=mode;st.minimized=false;saveTeacherWindowLayout(st);applyTeacherWindowLayout()}
function toggleTeacherMinimize(){const p=$('#studentsPanel'),st=loadTeacherWindowLayout();st.minimized=!st.minimized;if(st.mode==='float'&&!st.minimized){const r=p.getBoundingClientRect();st.x=r.left;st.y=r.top}saveTeacherWindowLayout(st);applyTeacherWindowLayout()}
function setupTeacherWindow(){const p=$('#studentsPanel'),head=$('#teacherControlDragHandle');if(!p||!head)return;applyTeacherWindowLayout();$('#teacherDockLeft').onclick=e=>{e.stopPropagation();setTeacherWindowMode('left')};$('#teacherFloat').onclick=e=>{e.stopPropagation();setTeacherWindowMode('float')};$('#teacherDockRight').onclick=e=>{e.stopPropagation();setTeacherWindowMode('right')};$('#teacherMinimize').onclick=e=>{e.stopPropagation();toggleTeacherMinimize()};$('#teacherClosePanel').onclick=e=>{e.stopPropagation();p.classList.add('hidden')};head.addEventListener('dblclick',e=>{if(!e.target.closest('button'))toggleTeacherMinimize()});head.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button'))return;const st=loadTeacherWindowLayout();if(st.mode!=='float'||st.minimized)return;const r=p.getBoundingClientRect();teacherDrag={dx:e.clientX-r.left,dy:e.clientY-r.top};head.setPointerCapture?.(e.pointerId);p.classList.add('dragging')});head.addEventListener('pointermove',e=>{if(!teacherDrag)return;const pos=clampTeacherWindow(p,e.clientX-teacherDrag.dx,e.clientY-teacherDrag.dy);p.style.left=pos.x+'px';p.style.top=pos.y+'px'});const end=e=>{if(!teacherDrag)return;teacherDrag=null;p.classList.remove('dragging');const r=p.getBoundingClientRect(),st=loadTeacherWindowLayout();st.mode='float';st.x=r.left;st.y=r.top;saveTeacherWindowLayout(st);head.releasePointerCapture?.(e.pointerId)};head.addEventListener('pointerup',end);head.addEventListener('pointercancel',end);window.addEventListener('resize',()=>{if(!p.classList.contains('hidden'))applyTeacherWindowLayout()})}
function classroomUrls(){if(!classroom?.room_code)return null;const base=new URL('.',location.href);return{student:new URL('student.html?room='+classroom.room_code,base).href,present:new URL('present.html?room='+classroom.room_code,base).href}}
function phaseLabel(v){return({free:'Freie Phase',explain:'Erklärung',solo:'Einzelarbeit',group:'Gruppenarbeit',class:'Klassenaufgabe',break:'Pause'})[v]||v||'–'}
