function setTeacherControlsEnabled(enabled){['#classroomPhase','#classroomTraffic','#classLockAll','#classWriteAll','#classFollowAll','#classFreeze','#classMessage','#sendClassMessage','#closeClassroom','#toggleContributions','#contributionFilter','#clearContributions'].forEach(id=>{const el=$(id);if(el)el.disabled=!enabled})}
function updateClassroomPanel(){const active=!!classroom?.room_code,code=active?classroom.room_code:'------',urls=classroomUrls();$('#roomCodeValue').textContent=code;$('#roomInfo').textContent=active?'Raum ist aktiv. Steuerung wird live synchronisiert.':'Noch kein Raum gestartet.';$('#classroomLiveDot').classList.toggle('on',active);['#copyRoomCode','#openPresentation','#openStudentView','#copyStudentLink','#showClassroomQr'].forEach(id=>{const el=$(id);if(el)el.disabled=!active});setTeacherControlsEnabled(active);if(active){$('#openPresentation').onclick=()=>window.open(urls.present,'_blank','noopener');$('#openStudentView').onclick=()=>window.open(urls.student,'_blank','noopener');$('#copyRoomCode').onclick=async()=>{await navigator.clipboard.writeText(code);toast('Raumcode kopiert')};$('#copyStudentLink').onclick=async()=>{await navigator.clipboard.writeText(urls.student);toast('Schülerlink kopiert')};$('#showClassroomQr').onclick=()=>showClassroomReady({name:teacherControlState?.class_name||'Klassenraum'})}else{$('#roomConnectedCount').textContent='0';$('#roomRosterCount').textContent='–';$('#roomHelpCount').textContent='0';$('#participantSummary').textContent='0 verbunden';$('#participantList').innerHTML='<div class="participantEmpty">Noch niemand verbunden.</div>';$('#teacherPollState').textContent='nicht verbunden'}}
let classroomSyncHash='',classroomSyncBusy=false;
async function syncClassroom(force=false){if(!classroom?.session_id||!classroom?.teacher_token||classroomSyncBusy)return;const data=serialize(),viewport={scale,tx,ty},signature=JSON.stringify([data,viewport]);if(!force&&signature===classroomSyncHash)return;classroomSyncBusy=true;try{const ok=await rpc('classroom_teacher_sync',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_board_state:data,p_viewport:viewport});if(ok)classroomSyncHash=signature;else throw Error('Classroom-Session ist nicht mehr aktiv')}catch(e){console.warn('Classroom sync',e)}finally{classroomSyncBusy=false}}
function startClassroomSync(){clearInterval(pollTimer);classroomSyncHash='';syncClassroom(true);pollTimer=setInterval(()=>syncClassroom(false),2200)}
async function teacherCommand(command,value={},participant=null,{quiet=false}={}){if(!classroom?.session_id)return false;try{const ok=await rpc('classroom_teacher_command',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_command:command,p_participant:participant,p_value:value});if(!ok)throw Error('Befehl wurde nicht übernommen');if(!quiet)toast('Klassenraum aktualisiert');await pollTeacherControl(true);return true}catch(e){console.error('Teacher command',command,e);toast('Steuerung fehlgeschlagen');return false}}
function ensureContributionLayer(){let cv=$('#classroomContributionInk');if(!cv){cv=document.createElement('canvas');cv.id='classroomContributionInk';cv.width=6000;cv.height=4000;cv.className='classroomContributionInk';world.appendChild(cv)}let textLayer=$('#classroomContributionText');if(!textLayer){textLayer=document.createElement('div');textLayer.id='classroomContributionText';textLayer.className='classroomContributionText';world.appendChild(textLayer)}return{cv,ctx:cv.getContext('2d'),textLayer}}
function contributionActiveEvents(events){const byStudent=new Map();for(const e of events){const id=e.participant_id,p=e.payload||{};if(!byStudent.has(id))byStudent.set(id,{legacy:[],snapshot:null,name:e.name});const bucket=byStudent.get(id);bucket.name=e.name||bucket.name;if(p.type==='snapshot'&&p.workspace){bucket.snapshot=e;bucket.legacy=[];continue}if(bucket.snapshot)continue;if(p.type==='clear')bucket.legacy=[];else if(p.type==='undo')bucket.legacy.pop();else if(p.type==='stroke'||p.type==='text')bucket.legacy.push(e)}const out=[];for(const [participant_id,b] of byStudent){if(b.snapshot){const ws=b.snapshot.payload.workspace||{};for(const st of ws.strokes||[])out.push({id:b.snapshot.id,participant_id,name:b.name,payload:{type:'stroke',stroke:st}});for(const item of ws.items||[])out.push({id:b.snapshot.id,participant_id,name:b.name,payload:{type:'workspace_item',item}})}else out.push(...b.legacy)}return out}
function renderTeacherContributions(){const {cv,ctx,textLayer}=ensureContributionLayer();cv.style.display=teacherContributionsVisible?'block':'none';textLayer.style.display=teacherContributionsVisible?'block':'none';ctx.clearRect(0,0,cv.width,cv.height);textLayer.innerHTML='';if(!teacherContributionsVisible)return;const active=contributionActiveEvents(teacherContributionEvents).filter(e=>teacherContributionFilter==='all'||e.participant_id===teacherContributionFilter);ctx.lineCap='round';ctx.lineJoin='round';for(const e of active){const p=e.payload||{};if(p.type==='stroke'&&p.stroke){const st=p.stroke;ctx.beginPath();ctx.strokeStyle=st.color||'#6d4d73';ctx.lineWidth=st.width||4;ctx.globalAlpha=st.alpha??1;(st.points||[]).forEach((pt,i)=>i?ctx.lineTo(pt.x,pt.y):ctx.moveTo(pt.x,pt.y));ctx.stroke();ctx.globalAlpha=1}else if(p.type==='text'){const el=document.createElement('div');el.className='studentContributionText';el.style.left=(+p.x||0)+'px';el.style.top=(+p.y||0)+'px';el.style.color=p.color||'#5b4164';el.style.fontSize=Math.min(96,Math.max(14,+p.size||28))+'px';el.style.fontWeight=p.bold?'900':'750';el.textContent=p.text||'';el.title=e.name||'';textLayer.appendChild(el)}else if(p.type==='workspace_item'&&p.item){const i=p.item,el=document.createElement('div');el.className='studentContributionItem '+(i.type||'');el.style.left=(+i.x||0)+'px';el.style.top=(+i.y||0)+'px';el.style.width=(+i.w||320)+'px';el.style.height=(+i.h||120)+'px';el.style.zIndex=10+(+i.z||0);if(i.type==='image'&&i.src){const im=document.createElement('img');im.src=i.src;im.alt=i.name||'Schülerbild';el.appendChild(im)}else{el.textContent=i.text||'';el.style.color=i.color||'#5b4164';el.style.background=i.type==='sticky'?(i.bg||'#fff0a9'):(i.bg||'rgba(255,255,255,.88)');el.style.fontSize=Math.min(96,Math.max(14,+i.size||28))+'px';el.style.fontWeight=i.bold?'900':'500';el.style.fontFamily=i.font||'Inter,Arial,sans-serif';el.style.textAlign=i.align||'left';el.style.whiteSpace='pre-wrap'}el.title=e.name||'';textLayer.appendChild(el)}}const count=active.length;$('#contributionSummary').textContent=count+' '+(count===1?'Beitrag':'Beiträge')}
async function pollTeacherContributions(reset=false){if(!classroom?.session_id||teacherContributionBusy)return;teacherContributionBusy=true;try{if(reset){teacherContributionAfterId=0;teacherContributionEvents=[]}const r=await rpc('classroom_teacher_contributions',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_after_id:teacherContributionAfterId});if(!r?.ok)throw Error('Contributions ungültig');const incoming=Array.isArray(r.events)?r.events:[];if(incoming.length)teacherContributionEvents.push(...incoming);teacherContributionAfterId=Number(r.last_id)||teacherContributionAfterId;renderTeacherContributions()}catch(e){console.warn('Teacher contributions',e);$('#contributionSummary').textContent='SQL-Patch erforderlich'}finally{teacherContributionBusy=false}}
function updateContributionFilter(){const sel=$('#contributionFilter'),ps=teacherControlState?.participants||[],current=teacherContributionFilter;sel.innerHTML='<option value="all">Alle Schüler</option>'+ps.map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join('');if([...sel.options].some(o=>o.value===current))sel.value=current;else{teacherContributionFilter='all';sel.value='all'}}
function renderParticipantList(){const list=$('#participantList'),all=teacherControlState?.participants||[],rows=all.filter(p=>participantFilter==='all'||p.state===participantFilter);if(!rows.length){list.innerHTML='<div class="participantEmpty">'+(all.length?'Keine Schüler in diesem Filter.':'Noch niemand verbunden.')+'</div>';return}list.innerHTML=rows.map(p=>'<article class="participantCard '+(p.online?'online':'offline')+' '+(p.state==='help'?'needsHelp':'')+'"><div class="participantMain"><span class="participantDot"></span><div><b>'+esc(p.name)+'</b><small>'+participantStateLabel(p.state)+' · '+(p.online?'online':'offline')+'</small></div><span class="participantState state-'+esc(p.state)+'">'+participantStateLabel(p.state)+'</span></div><div class="participantControls"><button data-p-action="lock" data-id="'+p.id+'" data-on="'+(p.locked?'1':'0')+'">'+(p.locked?'🔒 Gesperrt':'🔓 Frei')+'</button><button data-p-action="write" data-id="'+p.id+'" data-on="'+(p.can_write?'1':'0')+'">'+(p.can_write?'✏️ Schreiben':'✏️ Lesen')+'</button><button data-p-action="follow" data-id="'+p.id+'" data-on="'+(p.follow_teacher?'1':'0')+'">'+(p.follow_teacher?'👀 Folgt':'👀 Frei')+'</button><button data-p-action="message" data-id="'+p.id+'" data-name="'+esc(p.name)+'">💬</button></div></article>').join('');$$('[data-p-action]').forEach(btn=>btn.onclick=async()=>{const id=btn.dataset.id,act=btn.dataset.pAction,on=btn.dataset.on==='1';if(act==='lock')await teacherCommand(on?'unlock_one':'lock_one',{},id);else if(act==='write')await teacherCommand('write_one',{enabled:!on},id);else if(act==='follow')await teacherCommand('follow_one',{enabled:!on},id);else if(act==='view'){teacherContributionFilter=id;$('#contributionFilter').value=id;teacherContributionsVisible=true;$('#toggleContributions').dataset.on='1';$('#toggleContributions').textContent='👁 Beiträge sichtbar';renderTeacherContributions()}else if(act==='message'){const body=prompt('Nachricht an '+btn.dataset.name+':');if(body?.trim())await teacherCommand('message',{body:body.trim()},id)}})}
function renderTeacherControl(){const s=teacherControlState;if(!s?.ok)return;const ps=Array.isArray(s.participants)?s.participants:[],online=ps.filter(p=>p.online).length,help=ps.filter(p=>p.state==='help').length,roster=Number.isFinite(+s.roster_count)?+s.roster_count:null;$('#roomConnectedCount').textContent=online;$('#roomRosterCount').textContent=roster??'–';$('#roomHelpCount').textContent=help;$('#participantSummary').textContent=online+(roster!==null?' / '+roster:'')+' verbunden';$('#teacherPollState').textContent='live · '+phaseLabel(s.phase);$('#classroomPhase').value=s.phase||'free';$('#classroomTraffic').value=s.traffic||'green';const any=ps.length>0,allLocked=typeof s.class_locked==='boolean'?s.class_locked:(any&&ps.every(p=>p.locked)),allWrite=typeof s.class_can_write==='boolean'?s.class_can_write:(any&&ps.every(p=>p.can_write)),allFollow=typeof s.class_follow_teacher==='boolean'?s.class_follow_teacher:(any&&ps.every(p=>p.follow_teacher));$('#classLockAll').dataset.on=allLocked?'1':'0';$('#classLockAll').textContent=allLocked?'🔒 Alle gesperrt':'🔓 Alle entsperrt';$('#classWriteAll').dataset.on=allWrite?'1':'0';$('#classWriteAll').textContent=allWrite?'✏️ Schreiben an':'✏️ Schreiben aus';$('#classFollowAll').dataset.on=allFollow?'1':'0';$('#classFollowAll').textContent=allFollow?'👀 Lehreransicht':'👀 Freie Ansicht';$('#classFreeze').dataset.on=s.frozen?'1':'0';$('#classFreeze').textContent=s.frozen?'⏸ Beamer eingefroren':'▶ Beamer live';renderParticipantList();updateContributionFilter();refreshSeatingWidgets()}
async function pollTeacherControl(force=false){if(!classroom?.session_id||teacherControlBusy)return;teacherControlBusy=true;try{const state=await rpc('classroom_teacher_state',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token});if(!state?.ok)throw Error('Session ungültig');teacherControlState=state;window.KathleenClassLists?.updateClassroomState?.({className:state.class_name||window.KathleenClassLists?.getGlobalClass?.()?.name||'',connectedCount:(state.participants||[]).filter(p=>p.online).length,rosterCount:Number(state.roster_count)||0,sessionState:state.session_state||'open'});renderTeacherControl();$('#classroomLiveDot').classList.add('on');pollTeacherContributions(false);refreshLivePollWidgets();refreshGlobalClassPill()}catch(e){console.warn('Teacher control polling',e);$('#teacherPollState').textContent='Verbindung unterbrochen';$('#classroomLiveDot').classList.remove('on');if(force)toast('Teacher Control nicht erreichbar')}finally{teacherControlBusy=false}}
function startTeacherControl(){clearInterval(teacherControlTimer);teacherContributionAfterId=0;teacherContributionEvents=[];pollTeacherControl(true);pollTeacherContributions(true);teacherControlTimer=setInterval(()=>pollTeacherControl(false),1800)}
function stopTeacherControl(){clearInterval(teacherControlTimer);teacherControlTimer=null;teacherControlState=null}
function renderClassroomSetup(){const lists=window.KathleenClassLists?.load?.()||[],sel=$('#classroomClassSelect');sel.innerHTML=lists.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+' · '+c.students.length+' Schüler</option>').join('');const last=window.KathleenClassLists?.getGlobalClass?.()?.id||localStorage.getItem('kathleenLastClassroomClass');if(last&&lists.some(c=>c.id===last))sel.value=last;const renderPreview=()=>{const c=lists.find(x=>x.id===sel.value);$('#classroomRosterPreview').innerHTML=c?'<b>'+esc(c.name)+'</b><span>'+c.students.length+' Schüler</span><div>'+c.students.slice(0,10).map(n=>'<i>'+esc(n)+'</i>').join('')+(c.students.length>10?'<i>+'+(c.students.length-10)+'</i>':'')+'</div>':'<span>Keine Klasse gewählt.</span>'};sel.onchange=renderPreview;renderPreview();return lists}
function showClassroomReady(classInfo){const urls=classroomUrls();$('#classroomSetupStep').classList.add('hidden');$('#classroomReadyStep').classList.remove('hidden');$('#classroomReadyTitle').textContent=classInfo?.name||teacherControlState?.class_name||'Klassenraum';$('#classroomReadyCode').textContent=classroom.room_code;const q=$('#classroomQr');q.innerHTML='';if(window.QRCode)new QRCode(q,{text:urls.student,width:220,height:220,correctLevel:QRCode.CorrectLevel.M});$('#classroomReadyBeamer').onclick=()=>window.open(urls.present,'_blank','noopener');$('#classroomReadyStudent').onclick=()=>window.open(urls.student,'_blank','noopener');$('#classroomReadyCopy').onclick=async()=>{await navigator.clipboard.writeText(urls.student);toast('Schülerlink kopiert')};$('#classroomStartModal').classList.remove('hidden')}
