$('#roomBtn').onclick=openClassroomSetup;$('#classroomStartClose').onclick=()=>$('#classroomStartModal').classList.add('hidden');$('#classroomStartModal').onclick=e=>{if(e.target.id==='classroomStartModal')$('#classroomStartModal').classList.add('hidden')};
$('#classroomStartConfirm').onclick=async()=>{const lists=window.KathleenClassLists?.load?.()||[],selected=lists.find(x=>x.id===$('#classroomClassSelect').value);if(!selected)return;try{const pass=sessionStorage.getItem('kathleenAdminPass')||prompt('Kisten-Adminpasswort');if(!pass)return;const verified=!!(await rpc('classroom_authenticate',{p_passphrase:pass}));if(!verified){sessionStorage.removeItem('kathleenAdminPass');toast('Admin-Passwort falsch');return}classroom=await rpc('classroom_create',{p_passphrase:pass,p_title:board.name||'Unterricht',p_class_name:selected.name});const rosterOk=await rpc('classroom_set_roster',{p_session:classroom.session_id,p_teacher_token:classroom.teacher_token,p_class_name:selected.name,p_names:selected.students});if(!rosterOk)throw Error('Klassenliste konnte nicht übertragen werden');const rosterCheck=await rpc('classroom_roster',{p_room_code:classroom.room_code});if(!rosterCheck?.ok||!Array.isArray(rosterCheck.students)||rosterCheck.students.length!==selected.students.length)throw Error('Klassenliste ist serverseitig nicht bereit');sessionStorage.setItem('kathleenAdminPass',pass);sessionStorage.setItem('kathleenClassroom',JSON.stringify(classroom));localStorage.setItem('kathleenLastClassroomClass',selected.id);window.KathleenClassLists?.setGlobalClass?.(selected.id,selected.name);classroom=window.KathleenClassLists?.setClassroomState?.(classroom,{classId:selected.id,className:selected.name,rosterCount:selected.students.length,connectedCount:0,sessionState:'open'})||classroom;updateClassroomPanel();refreshGlobalClassPill();$('#studentsPanel').classList.remove('hidden');$('#studentsPanel').classList.add('teacherPersistent');applyTeacherWindowLayout();startClassroomSync();startTeacherControl();showClassroomReady(selected);toast('Raum '+classroom.room_code+' gestartet')}catch(e){console.error(e);const m=String(e.message||'');if(/classroom_|schema cache|function .* does not exist|PGRST202/i.test(m))toast('Classroom-SQL fehlt oder ist veraltet');else toast('Raumstart: '+m.slice(0,90))}};
